const EMOJI_RULES = [
  [/야키소바/, '🍝'], [/오므라이스|양식/, '🍳'], [/츠케멘|라멘|중화소바/, '🍜'], [/소바|우동/, '🥢'], [/스시|초밥/, '🍣'], [/텐동|덴푸라/, '🍤'],
  [/장어|우나기|아나고/, '🍱'], [/해산물|시라스|정어리/, '🐟'], [/돈카츠|카츠/, '🐷'], [/야키니쿠|함박/, '🥩'],
  [/야키토리|닭|오야코/, '🍗'], [/교자/, '🥟'], [/카레/, '🍛'], [/오뎅/, '🍢'], [/몬자/, '🥘'],
  [/비리야니|인도|케밥/, '🫓'], [/중식|쓰촨/, '🥡'], [/이자카야/, '🍶'],
  [/젤라토|아이스/, '🍦'], [/파르페/, '🍨'], [/타이야키|화과자|당고|도라야키|아마미|만주/, '🍡'], [/차$|말차/, '🍵'],
  [/팬케이크|핫케이크/, '🥞'], [/프렌치토스트|베이커리/, '🥐'], [/킷사텐|커피|카페/, '☕'],
];
export const eatEmoji = e => EMOJI_RULES.find(([re]) => re.test(e.genre))?.[1] || (e.kind === 'cafe' ? '☕' : '🍽️');

// 지역과 구역. 맛집의 area 값이 구역 id
export const EAT_REGIONS = [
  { id: 'shizuoka', label: '시즈오카', center: { lat: 34.9717, lng: 138.3889 }, areas: [['shizuoka', '시즈오카 시내'], ['shimizu', '시미즈'], ['fuji', '후지·후지노미야']] },
  { id: 'tokyo', label: '도쿄', center: { lat: 35.6812, lng: 139.7671 }, areas: [
    ['shinjuku', '신주쿠'], ['shibuya', '시부야·하라주쿠'], ['ebisu', '에비스·나카메구로'], ['roppongi', '롯폰기·아자부'], ['ikebukuro', '이케부쿠로'],
    ['ginza', '긴자·유라쿠초'], ['tokyo-st', '도쿄역·니혼바시'], ['tsukiji', '츠키지·도요스·츠키시마'], ['asakusa', '아사쿠사·우에노'], ['akihabara', '아키하바라·간다']] },
];
const AREA_REGION = Object.fromEntries(EAT_REGIONS.flatMap(r => r.areas.map(([a]) => [a, r.id])));
export const regionOf = e => AREA_REGION[e.area];
export const areaLabel = id => EAT_REGIONS.flatMap(r => r.areas).find(([a]) => a === id)?.[1] || '';
export const eatsIn = regionId => EATS.filter(e => regionOf(e) === regionId);

// 기준 위치에서 가장 가까운 지역 (없으면 null)
export function nearestRegion(center, maxKm = 120) {
  let best = null, bestKm = Infinity;
  for (const r of EAT_REGIONS) { const km = haversineKm(center, r.center); if (km < bestKm) { best = r; bestKm = km; } }
  return bestKm <= maxKm ? best : null;
}

// 기준 위치에서 radiusKm 안의 맛집
export function eatsNear(center, radiusKm = 80) {
  return EATS.filter(e => haversineKm(center, e) <= radiusKm);
}
